good.code:
const inventoryBreaker = new CircuitBreaker({
  failureRateThreshold: 0.5,   // open when half the calls fail
  minimumCalls: 20,            // ...out of at least 20 in the window
  windowMs: 10_000,
  openMs: 15_000,              // cool-down before half-open
  halfOpenProbes: 3,
  isFailure: err => err.timeout || err.status >= 500, // not 4xx
})

async function getStock(sku) {
  try {
    return await inventoryBreaker.run(() =>
      fetchJson(`${INVENTORY}/stock/${sku}`, { timeoutMs: 800 }))
  } catch (err) {
    metrics.inc('stock_fallback', { reason: err.code })
    return stockCache.get(sku) ?? { sku, status: 'unknown' }
  }
}

